*   **`data-sort` Attribute:**  This is the key.  We add a `data-sort` attribute to each `<th>` (table header).  This attribute tells our JavaScript what type of sorting to apply to that column.  Common values are:
    *   `string`: For text-based columns (names, descriptions, etc.).  Sorts alphabetically.
    *   `number`: For numeric columns (age, price, quantity, etc.).  Sorts numerically.
    *   `date`: For date columns.  Sorts chronologically.  (You'll need to ensure your dates are in a consistent format, like YYYY-MM-DD).

**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');
let sortColumn = null;
let sortOrder = 1; // 1 = ascending, -1 = descending

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const header = event.target;
    const columnIndex = header.cellIndex;
    const sortType = header.dataset.sort;

    if (sortColumn === columnIndex) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(sortColumn, sortOrder, sortType);
  }
});

function sortTable(column, order, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.cells[column].textContent;
    const cellB = b.cells[column].textContent;

    let comparison = 0;

    switch (sortType) {
      case 'number':
        comparison = Number(cellA) - Number(cellB);
        break;
      case 'date':
        comparison = new Date(cellA) - new Date(cellB);
        break;
      default: // string
        comparison = cellA.localeCompare(cellB);
    }

    return order * comparison;
  });

  // Clear the table body and re-append sorted rows
  table.querySelector('tbody').innerHTML = '';
  rows.forEach(row => table.querySelector('tbody').appendChild(row));
}
```

